export const Icon: React.FC<IconProps> = ({
  name,
  size = 20,
  color,
  image,
  ariaHidden = true,
  ariaLabel,
  className = '',
  style,
  ...rest
}) => {
  // If icon is 'image' or has an image source provided
  if (name === 'image' && image) {
    return (
      <img
        src={image}
        alt={ariaLabel || ''}
        aria-hidden={ariaHidden && !ariaLabel}
        className={`inline-block object-contain ${className}`}
        style={{ width: size, height: size, ...style }}
      />
    );
  }

  const Component = iconRegistry[name];

  if (!Component) {
    if (import.meta.env.DEV) {
      console.error(`[IconRegistry] Icon ID "${name}" is not registered in iconRegistry.`);
    }
    // Fallback indicator so layout does not break
    return (
      <span
        className={`inline-block border border-dashed border-line text-ink-muted text-xs font-mono px-1 rounded ${className}`}
        title={`Missing icon: ${name}`}
        aria-hidden={ariaHidden}
        style={style}
      >
        {name}
      </span>
    );
  }

  const isFilled = filledIconNames.has(name);

  return (
    <Component
      width={size}
      height={size}
      stroke={isFilled ? undefined : (color || 'currentColor')}
      fill={isFilled ? 'currentColor' : undefined}
      style={{ color: color || undefined, ...style }}
      className={`inline-block shrink-0 ${className}`}
      aria-hidden={ariaHidden && !ariaLabel ? 'true' : undefined}
      aria-label={ariaLabel}
      role={ariaLabel ? 'img' : undefined}
      {...rest}
    />
  );
};

export function hasIcon(name: string): boolean {
  return Boolean(iconRegistry[name]) || name === 'image';
}

export const registeredIconNames = Object.keys(iconRegistry);
